+import { daysLeft, isExpired } from "./expiry.js";
+
+/** Builds a summary of the shelf at the given time. */
+export function buildReport(items, now = Date.now()) {
+  const active = [];
+  const expired = [];
+  for (const item of items) {
+    if (isExpired(item, now)) expired.push(item.name);
+    else active.push(item);
+  }
+
+  const tags = new Map();
+  for (const item of active) {
+    for (const tag of new Set(item.tags)) tags.set(tag, (tags.get(tag) || 0) + 1);
+  }
+  const compare = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
+  return {
+    generatedAt: new Date(now).toISOString(),
+    total: active.length,
+    units: active.reduce((sum, item) => sum + item.qty, 0),
+    byTag: Object.fromEntries([...tags].sort(([a], [b]) => compare(a, b))),
+    expiringSoon: active
+      .filter((item) => daysLeft(item, now) <= 3)
+      .sort((a, b) => Date.parse(a.expires) - Date.parse(b.expires) || compare(a.name, b.name))
+      .map((item) => item.name),
+    expired: expired.sort(compare),
+  };
+}
